                err_preview = " ".join(f"Row {i}: {repr(v)}" for i, v, _ in bad_rows[:sample])

                raise ValueError(
                    f"Failed converting Series '{series.name}' to dtype {dtype!r} due to {len(bad_rows)} failed cases, such as \n"
                    f"{err_preview}"
                )

            return pd.Series(results, index=series.index, name=series.name)

